// The Mongolian grade-placement banks. CLIENT-SAFE: imports only the small
// per-bank tables in i18n/placement-tables/ (never a lesson mirror, never
// the bank corpus — lib/genmath-split.test.ts fences the placement graph).
//
// A table is keyed per bank because question ids (`${slug}:d${n}`) collide
// across banks. Shape:
//   { "topics":    { "<slug>": "<Mongolian topic title>" },   // generated by
//                                                             // scripts/i18n/mn_placement_topics.py
//     "questions": { "<id>": { "prompt", "options", "explanation" } } }
//
// The Mongolian bank is the English bank with each question's text swapped
// in from the table. Ids, difficulty, topicSlug and correctIndex always come
// from the English, and a question the table lacks stays English, so a
// half-written table degrades to a mixed sitting rather than a broken one.
// lib/placement-bank-mn.test.ts holds the maths and answer key fixed.

import {
  getPlacementBank,
  getGeometryPlacementBank,
  getGrade7PlacementBank,
  getGrade8PlacementBank,
  getGrade9PlacementBank,
  getGrade10PlacementBank,
  getGrade11PlacementBank,
  getGrade12PlacementBank,
  type PlacementQuestion,
} from "@/lib/placement-bank";
import t6 from "@/i18n/placement-tables/6.mn.json";
import tGeometry from "@/i18n/placement-tables/geometry.mn.json";
import t7 from "@/i18n/placement-tables/7.mn.json";
import t8 from "@/i18n/placement-tables/8.mn.json";
import t9 from "@/i18n/placement-tables/9.mn.json";
import t10 from "@/i18n/placement-tables/10.mn.json";
import t11 from "@/i18n/placement-tables/11.mn.json";
import t12 from "@/i18n/placement-tables/12.mn.json";

export type PlacementTableQuestion = { prompt: string; options: string[]; explanation: string };
export type PlacementTable = {
  topics: Record<string, string>;
  questions: Record<string, PlacementTableQuestion>;
};

export type PlacementBankId = "6" | "geometry" | "7" | "8" | "9" | "10" | "11" | "12";

/** Every bank: its English getter and its Mongolian table. */
export const PLACEMENT_BANKS: Record<PlacementBankId, { en: () => PlacementQuestion[]; table: PlacementTable }> = {
  "6": { en: getPlacementBank, table: t6 as PlacementTable },
  geometry: { en: getGeometryPlacementBank, table: tGeometry as PlacementTable },
  "7": { en: getGrade7PlacementBank, table: t7 as PlacementTable },
  "8": { en: getGrade8PlacementBank, table: t8 as PlacementTable },
  "9": { en: getGrade9PlacementBank, table: t9 as PlacementTable },
  "10": { en: getGrade10PlacementBank, table: t10 as PlacementTable },
  "11": { en: getGrade11PlacementBank, table: t11 as PlacementTable },
  "12": { en: getGrade12PlacementBank, table: t12 as PlacementTable },
};

/** The English bank with the table's Mongolian swapped in, per question. */
export function localizePlacementBank(bank: PlacementQuestion[], table: PlacementTable): PlacementQuestion[] {
  return bank.map((q) => {
    const t = table.questions[q.id];
    const topicTitle = table.topics[q.topicSlug] ?? q.topicTitle;
    // An option-count mismatch would misalign the answer key: keep English.
    if (!t || t.options.length !== q.options.length) return { ...q, topicTitle };
    return { ...q, topicTitle, prompt: t.prompt, options: t.options, explanation: t.explanation };
  });
}

const cache = new Map<PlacementBankId, PlacementQuestion[]>();

export function getPlacementBankMn(bank: PlacementBankId): PlacementQuestion[] {
  const hit = cache.get(bank);
  if (hit) return hit;
  const { en, table } = PLACEMENT_BANKS[bank];
  const out = localizePlacementBank(en(), table);
  cache.set(bank, out);
  return out;
}
